python3 - <<'EOF'
p='index.html'; s=open(p).read()
old="""    var o4=place('2026-10-07T04:00:00Z', true, [['P05-400',1]], 'MAN800', A[3]);
    at('2026-10-07T04:05:00Z'); corePay(o4); at('2026-10-08T02:00:00Z'); coreShip(o4);
    at('2026-10-10T09:00:00Z'); coreRequestAfterSale(o4, [{sku:'P05-400', qty:1}], {returnGoods:false, reason:'外盒破损，协商部分补偿'});
    // 注：上面为整件仅退款示例会退全额，改为部分补偿更合理 —— 见下方修正
"""
new="""    var o4=place('2026-10-07T04:00:00Z', true, [['P05-400',1],['P07-1',1]], 'MAN800', A[3]);
    at('2026-10-07T04:05:00Z'); corePay(o4); at('2026-10-08T02:00:00Z'); coreShip(o4);
    at('2026-10-10T09:00:00Z'); coreRequestAfterSale(o4, [{sku:'P07-1', qty:1}], {returnGoods:false, reason:'展示盒运输破损，不必寄回'});
"""
assert old in s; s=s.replace(old,new)
old="""else if(t.hasAttribute('data-asqty')){ var n=toInt(t.value.trim()); ui.asQty[t.getAttribute('data-asqty')]=(n>=0||t.value.trim()==='')?(n||0):NaN; if(t.value.trim()!=='' && !(n>=0)) ui.asQty[t.getAttribute('data-asqty')]=-1; updateASPreview(); }"""
new="""else if(t.hasAttribute('data-asqty')){ var raw=t.value.trim(); ui.asQty[t.getAttribute('data-asqty')]=raw===''?0:toInt(raw); updateASPreview(); }"""
assert old in s; s=s.replace(old,new)
old="""Object.keys(ui.asQty).forEach(function(k){ if(ui.asQty[k]>0) out.push"""
new="""Object.keys(ui.asQty).forEach(function(k){ if(ui.asQty[k]!==0) out.push"""
assert old in s; s=s.replace(old,new)
old="""returnGoods:false, restocked:true, kind:'cancel',"""
new="""returnGoods:false, restocked:true, kind:'cancel', orderStatus:'paid',"""
assert old in s; s=s.replace(old,new)
open(p,'w').write(s)
EOF

